-- Outreach v4 (Oct 2026): every small-business email names the full
-- automation menu, per the owner: websites, file management, AI voice agents,
-- and social media, tailored to the business. Same message as the AI phone
-- calls (ingest/bland-calls.js). Copy only; sending caps and switches are
-- unchanged. Re-runnable: it overwrites the same keys each time.
--
-- The mailing address is added by the code from the private
-- business_mailing_address row, never written here.

update settings set value = jsonb_set(
    jsonb_set(
      jsonb_set(value, '{touch_sets}', (value->'touch_sets') || $j${"website": [{"step": 1, "delay_days": 0, "subject": "a sample site for {business_name}", "body": "Hi,\n\nI came across {business_name} online and noticed your website {issue_line}. For a lot of local businesses, that's where people coming from Google drop off before they ever call. So I put together a quick sample of a refreshed site:\n\n{preview_url}\n\nI'm Deven, and I run Wade Capital. We build automation tailored to each business, for example:\n- a website that turns Google searches into calls and bookings\n- file management that names, sorts, and backs up your invoices, forms, and records automatically\n- an AI voice agent that answers your phone, takes messages, and books appointments, even after hours\n- social media that posts on its own\n\nEvery project is a fixed price, and we start with whichever one saves you the most time.\n\nWorth a 10-minute call this week to see what would fit {business_name}?\n\n{sender_name}"}], "both": [{"step": 1, "delay_days": 0, "subject": "a sample site for {business_name}", "body": "Hi,\n\nI came across {business_name} online and noticed your website {issue_line}. For a lot of local businesses, that's where people coming from Google drop off before they ever call. So I put together a quick sample of a refreshed site:\n\n{preview_url}\n\nI'm Deven, and I run Wade Capital. We build automation tailored to each business, for example:\n- a website that turns Google searches into calls and bookings\n- file management that names, sorts, and backs up your invoices, forms, and records automatically\n- an AI voice agent that answers your phone, takes messages, and books appointments, even after hours\n- social media that posts on its own\n\nEvery project is a fixed price, and we start with whichever one saves you the most time.\n\nWorth a 10-minute call this week to see what would fit {business_name}?\n\n{sender_name}"}], "social": [{"step": 1, "delay_days": 0, "subject": "{business_name} on social media", "body": "Hi,\n\nI was on {business_name}'s website and noticed it {issue_line}. More and more customers check Instagram or Facebook before they visit, and a page that posts regularly is often what tips them.\n\nI'm Deven, and I run Wade Capital. We build automation tailored to each business, for example:\n- a website that turns Google searches into calls and bookings\n- file management that names, sorts, and backs up your invoices, forms, and records automatically\n- an AI voice agent that answers your phone, takes messages, and books appointments, even after hours\n- social media that posts on its own\n\nEvery project is a fixed price, and we start with whichever one saves you the most time.\n\nWant me to put together a free sample week of posts for {business_name}, or set up a quick call to see what else would fit?\n\n{sender_name}"}], "no_website": [{"step": 1, "delay_days": 0, "subject": "a website for {business_name}", "body": "Hi,\n\nI was looking for {business_name} online and couldn't find a website, so I put together a quick mockup of what one could look like:\n\n{preview_url}\n\nIt's a starting point built from your Google listing.\n\nI'm Deven, and I run Wade Capital. We build automation tailored to each business, for example:\n- a website that turns Google searches into calls and bookings\n- file management that names, sorts, and backs up your invoices, forms, and records automatically\n- an AI voice agent that answers your phone, takes messages, and books appointments, even after hours\n- social media that posts on its own\n\nEvery project is a fixed price, and we start with whichever one saves you the most time.\n\nWorth a 10-minute call this week?\n\n{sender_name}"}], "after_call": [{"step": 1, "delay_days": 0, "subject": "your sample website", "body": "Hi,\n\nThanks for taking the call from my AI assistant (the same kind of voice agent we can set up to answer your phone). Here's the free sample website I put together for {business_name}:\n\n{preview_url}\n\nIt's built from your Google listing, so it's just a starting point. Beyond websites, Wade Capital builds automation tailored to your business: file management that organizes your paperwork automatically, AI voice agents that answer calls and book appointments, and social media that posts on its own. Every project is a fixed price.\n\nHappy to answer questions, or we can do a quick 10-minute call this week.\n\n{sender_name}"}]}$j$::jsonb),
      '{followups}', $j$[{"step": 2, "delay_days": 4, "subject": "{business_name}'s website", "body": "Hi, just bumping this in case it got buried.{mockup_line}\n\nQuick recap: Wade Capital builds automation tailored to your business, from websites and file management to AI voice agents that answer your phone and social media that posts itself. Happy to walk you through what would fit {business_name} on a quick call.\n\n{sender_name}"}, {"step": 3, "delay_days": 7, "subject": "{business_name}'s website", "body": "Hi, one more note. If now isn't a good time, no problem at all. If it helps, a 10-minute call is the easiest way to see which automation (website, files, phone, or social media) would save {business_name} the most time.\n\n{sender_name}"}, {"step": 4, "delay_days": 10, "subject": "{business_name}'s website", "body": "Hi, I'll stop following up after this one. If a website, file management, an AI phone agent, or social media automation ever becomes a priority for {business_name}, just reply here and I'll pick it up from there.\n\n{sender_name}"}]$j$::jsonb),
    '{automation_pivot,touches}', $j$[{"step": 3, "delay_days": 7, "subject": "{business_name}'s website", "body": "Hi,\n\nA different idea for {business_name}: most local businesses I talk to lose hours a week to missed calls, paperwork, and appointment reminders that could run on their own. Two examples of what we set up:\n- an AI voice agent that answers every call, takes messages, and books appointments, even after hours\n- file management that names, sorts, and backs up invoices and forms automatically\n\nI can start with a fixed-fee Automation Readiness Audit: a short call and a written list of what's worth automating first, with no commitment to build anything.\n\nWant me to send the details?\n\n{sender_name}"}, {"step": 4, "delay_days": 10, "subject": "{business_name}'s website", "body": "Hi, I'll stop following up after this one. If a website, file management, an AI phone agent, or social media automation ever becomes a priority for {business_name}, just reply here and I'll pick it up from there.\n\n{sender_name}"}]$j$::jsonb)
where key = 'outreach';
